'use strict';
const menu = document.querySelector('.menu-toggle');
const nav = document.querySelector('#nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Apri menu');nav.classList.remove('open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Chiudi menu':'Apri menu');nav.classList.toggle('open',open);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
window.matchMedia('(min-width:641px)').addEventListener('change',event=>{if(event.matches)closeMenu();});
const filters=document.querySelectorAll('[data-filter]');
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('.solution-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;});}));
const solutions={
 monitoraggio:{label:'01 / MONITORAGGIO OPERATIVO',title:'Dai segnali alle informazioni.',text:'Quando lo stato delle macchine è difficile da leggere, anche organizzare il lavoro diventa più complesso. Un sistema di monitoraggio può raccogliere i segnali utili e renderli consultabili in un unico punto.',items:['Individuare insieme quali dati servono davvero.','Valutare sensori, interfacce e accesso ai segnali delle macchine.','Progettare una vista chiara di stati, eventi e andamento dei processi.'],question:'Da valutare: disponibilità dei dati, compatibilità delle macchine e condizioni di installazione.',interest:'Monitoraggio di macchine e processi'},
 connessione:{label:'02 / IOT E INTEGRAZIONE',title:'Il mondo fisico incontra il digitale.',text:'Un dispositivo connesso mette in relazione ciò che succede sul campo con gli strumenti di chi lavora. Meccanica, elettronica e software vanno pensati come parti dello stesso prodotto.',items:['Definire le informazioni da scambiare e chi le utilizzerà.','Progettare l’integrazione fisica di sensori ed elettronica.','Valutare connettività, interfacce software e gestione degli accessi.'],question:'Da valutare: ambiente operativo, infrastruttura di rete e sistemi già presenti.',interest:'IoT e macchine connesse'},
 qualita:{label:'03 / AI E CONTROLLO QUALITÀ',title:'Insegnare alle macchine a osservare.',text:'La visione artificiale può aiutare a riconoscere difetti o differenze nei componenti. Si parte dai campioni reali per verificare dove l’AI può supportare chi si occupa di qualità.',items:['Definire caratteristiche e anomalie da riconoscere.','Raccogliere immagini rappresentative e valutarne la qualità.','Testare un prototipo con criteri misurabili e supervisione umana.'],question:'Da valutare: illuminazione, variabilità dei pezzi, dati disponibili e precisione richiesta.',interest:'AI e controllo qualità'},
 automazione:{label:'04 / PRODOTTI SU MISURA',title:'Progettare attorno al tuo lavoro.',text:'Le attività ripetitive hanno spesso esigenze molto specifiche. Un prodotto di nicchia nasce dall’osservazione del processo e combina meccanica e software nella misura necessaria.',items:['Osservare passaggi, tempi e vincoli dell’attività.','Individuare le parti del processo che si prestano all’automazione.','Realizzare un prototipo da validare nelle condizioni d’uso.'],question:'Da valutare: fattibilità, interazione con gli operatori e obiettivi del progetto.',interest:'Automazione su misura'}
};
const detailDialog=document.querySelector('#detail-dialog');
const dialogAction=document.querySelector('#dialog-action');
let selectedInterest='';
function addText(tag,text,parent){const element=document.createElement(tag);element.textContent=text;parent.append(element);return element;}
document.querySelectorAll('[data-solution]').forEach(card=>card.addEventListener('click',()=>{const data=solutions[card.dataset.solution];document.querySelector('#dialog-label').textContent=data.label;document.querySelector('#dialog-title').textContent=data.title;const body=document.querySelector('#dialog-body');body.replaceChildren();addText('p',data.text,body);const ul=document.createElement('ul');data.items.forEach(item=>addText('li',item,ul));body.append(ul);addText('p',data.question,body);selectedInterest=data.interest;dialogAction.hidden=false;detailDialog.showModal();}));
dialogAction.addEventListener('click',()=>{detailDialog.close();document.querySelector('[name=interest]').value=selectedInterest;document.querySelector('#progetto').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});document.querySelector('[name=name]').focus({preventScroll:true});});
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))dialog.close();});dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.style.overflow='';});});
const modalObserver=new MutationObserver(()=>{document.body.style.overflow=document.querySelector('dialog[open]')?'hidden':'';});document.querySelectorAll('dialog').forEach(d=>modalObserver.observe(d,{attributes:true,attributeFilter:['open']}));
let briefText='';
document.querySelector('#brief-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;const data=new FormData(form);const name=String(data.get('name')).trim(),company=String(data.get('company')).trim(),challenge=String(data.get('challenge')).trim();if(!name||!company||challenge.length<10){document.querySelector('#form-status').textContent='Inserisci nome, azienda e almeno 10 caratteri per descrivere la sfida.';return;}document.querySelector('#form-status').textContent='';briefText=`SAMERA — Design. Make. Connect.\nBRIEF DI PROGETTO\n\nNome: ${name}\nAzienda: ${company}\nAmbito: ${data.get('interest')}\n\nLA SFIDA\n${challenge}\n\nPROSSIMO PASSO\nCondividere questo riepilogo con il team Samera per un primo confronto su esigenze, fattibilità e obiettivi.\n\nDocumento preparato nel browser. Nessun dato è stato inviato automaticamente.`;document.querySelector('#brief-preview').textContent=briefText;document.querySelector('#copy-status').textContent='';document.querySelector('#brief-dialog').showModal();});
document.querySelector('#download-brief').addEventListener('click',()=>{const blob=new Blob([briefText],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='Samera-brief-progetto.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.querySelector('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(briefText);document.querySelector('#copy-status').textContent='Testo copiato.';}catch{document.querySelector('#copy-status').textContent='Copia non disponibile: usa “Scarica il brief”.';}});
document.querySelector('#privacy-button').addEventListener('click',()=>{document.querySelector('#dialog-label').textContent='PRIVACY E DATI';document.querySelector('#dialog-title').textContent='I tuoi dati, nel tuo browser.';const body=document.querySelector('#dialog-body');body.replaceChildren();addText('p','Questa versione del sito non utilizza strumenti di analisi, cookie di profilazione o archiviazione persistente dei dati del modulo. Le informazioni inserite vengono elaborate nel browser per creare un file di testo e non vengono inviate a Samera.',body);addText('p','Se scegli di copiare il brief, il testo viene scritto negli appunti del dispositivo. Se lo scarichi, il file viene salvato dal tuo browser. Le immagini di questo sito sono illustrazioni editoriali generate con AI e non rappresentano prodotti o impianti reali di Samera.',body);addText('p','I caratteri tipografici vengono caricati da Google Fonts, con una connessione ai server del fornitore. La piattaforma di hosting può gestire dati tecnici e autenticazione necessari per l’accesso al sito.',body);dialogAction.hidden=true;detailDialog.showModal();});
document.querySelector('#year').textContent=new Date().getFullYear();
